// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 deposit, uint256 amount) public {
        vm.assume(deposit <= VALUE_CAP);
        deposit = bound(deposit, 0, 1e30);
        amount = bound(amount, 0, 1e36);
        // Admissible domain: withdraw an amount STRICTLY GREATER than the balance.
        vm.assume(amount > deposit);

        // fund the test contract (which is c's owner) and deposit into c via fallback
        vm.deal(address(this), deposit);
        (bool sent, ) = address(c).call{value: deposit}("");
        require(sent, "deposit failed");
        require(address(c).balance == deposit, "balance mismatch");

        // owner withdraws more than c holds
        vm.prank(address(this));
        bool ok;
        try c.withdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: an over-withdrawal (amount > address(c).balance) must REVERT,
        // since the reference performs a transfer of `amount` which cannot succeed.
        // The mutant deleted the transfer, so it succeeds — breaking the rule.
        assertTrue(!ok);
    }
}
